package com.slotix.reservationcore.availability; import jakarta.validation.*; import org.springframework.http.*; import org.springframework.security.access.prepost.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/companies/{companyId}/resources/{resourceId}/blocks") public class ResourceBlockController{final ResourceBlockService service;public ResourceBlockController(ResourceBlockService s){service=s;}@GetMapping @PreAuthorize("hasAnyRole('COMPANY_ADMIN','BOOKING_MANAGER','CUSTOMER')") List<ResourceBlockResponse> list(@PathVariable UUID companyId,@PathVariable UUID resourceId){return service.list(companyId,resourceId);}@PostMapping @PreAuthorize("hasRole('COMPANY_ADMIN')") ResponseEntity<ResourceBlockResponse> create(@PathVariable UUID companyId,@PathVariable UUID resourceId,@Valid @RequestBody CreateResourceBlockRequest q){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(companyId,resourceId,q));}}
